// Live-DB coverage for the S2.3 creation flow: create (POST) -> list (GET) ->
// edit (PATCH), plus the one-step GANADA conversion, driven through the REAL
// route handlers so real SQL, joins, the autogenerated code and the
// `auditoria_cambios` ledger are proven rather than mocked.
//
// Every path runs inside one forced-rollback transaction: the route handlers
// are pointed at a test-only Prisma client that joins the ambient transaction
// (a Proxy over a hoisted holder, with `$transaction(fn)` = `fn(holder.tx)`).
// `auditoria_cambios` is append-only, so nothing may be cleaned up afterwards —
// the rollback is the only safe shape, and the demo's first allocation must
// still be `PRY-2026-001`.
//
// `./require-local-db` must stay the FIRST import — it loads `.env.local` and
// refuses any non-loopback target before the Prisma client is built.
import "./require-local-db";

import { randomUUID } from "node:crypto";

import { Prisma, PrismaClient, type Usuario } from "@prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

const holder = vi.hoisted(() => ({ tx: null as unknown }));

vi.mock("@/lib/supabase/server", () => ({ requireApiUser: vi.fn() }));

// The routes read/write through `@/lib/db`; the proxy forwards every model
// delegate to the ambient test transaction so the whole flow shares one tx and
// rolls back together. `$transaction(fn)` runs the route's callback against the
// same tx instead of opening a nested one.
//
// The `pg` driver adapter emits a benign deprecation warning ("client.query()
// when the client is already executing a query") on this path: the ambient
// interactive transaction already owns the connection while the route's nested
// `$transaction(fn)` runs its queries on that same transaction client. It is
// inherent to joining the ambient transaction and does not affect the
// assertions (every run still rolls back cleanly).
vi.mock("@/lib/db", () => ({
  db: new Proxy({} as Record<string, unknown>, {
    get(_target, prop) {
      if (prop === "$transaction") {
        return async (fn: (tx: unknown) => Promise<unknown>) => fn(holder.tx);
      }
      const source = holder.tx as Record<string, unknown> | null;
      if (!source) {
        throw new Error(`db.${String(prop)} was used outside the test transaction`);
      }
      const value = source[prop as string];
      return typeof value === "function" ? value.bind(source) : value;
    },
  }),
}));

import { requireApiUser } from "@/lib/supabase/server";
import { GET as listProjects, POST as createProject } from "@/app/api/v1/projects/route";
import { GET as listEligible } from "@/app/api/v1/projects/eligible-opportunities/route";
import { PATCH as patchProject } from "@/app/api/v1/projects/[id]/route";
import { POST as createFromOpportunity } from "@/app/api/v1/clients/[id]/opportunities/[opportunityId]/project/route";

const TX_OPTIONS = { timeout: 20_000, maxWait: 10_000 };

const prisma = new PrismaClient({
  adapter: new PrismaPg({ connectionString: process.env.DATABASE_URL }),
});

type Tx = Prisma.TransactionClient;

/** Thrown to force a rollback even when the body succeeded. */
class IntentionalRollback extends Error {}

async function runAndRollback<T>(fn: (tx: Tx) => Promise<T>): Promise<T> {
  let captured: T | undefined;
  try {
    await prisma.$transaction(async (tx) => {
      holder.tx = tx;
      captured = await fn(tx);
      throw new IntentionalRollback();
    }, TX_OPTIONS);
  } catch (error) {
    if (!(error instanceof IntentionalRollback)) throw error;
  } finally {
    holder.tx = null;
  }
  return captured as T;
}

/** Real rows the route will join against; all rolled back with the flow. */
async function seedFixture(tx: Tx) {
  const suffix = randomUUID();
  const usuario = await tx.usuario.create({
    data: { email: `flow-${suffix}@example.test`, nombre: "flow-fixture" },
  });
  const cliente = await tx.cliente.create({
    data: { nombre: `flow-cliente-${suffix}`, tipo_cliente: "OTRO", responsable_id: usuario.id },
  });
  const linea = await tx.lineaEstrategicaCatalogo.create({
    data: { codigo: `LE-FLOW-${suffix}`, nombre: `flow-linea-${suffix}` },
  });
  const municipio = await tx.municipio.create({
    data: { nombre: `flow-mun-${suffix}`, departamento: "Antioquia" },
  });
  return { suffix, usuario, cliente, linea, municipio };
}

function authAs(usuarioId: string) {
  vi.mocked(requireApiUser).mockResolvedValue({
    ok: true,
    usuario: { id: usuarioId, rol: "GERENCIA" } as Usuario,
    supabaseUser: {} as never,
  });
}

function jsonRequest(url: string, method: string, body: unknown): Request {
  return new Request(url, {
    method,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

async function rowCounts() {
  const [proyectos, secuencias, auditoria] = await Promise.all([
    prisma.proyecto.count(),
    prisma.proyectoSecuencia.count(),
    prisma.auditoriaCambio.count(),
  ]);
  return { proyectos, secuencias, auditoria };
}

beforeAll(async () => {
  await prisma.$connect();
});

afterAll(async () => {
  const counts = await rowCounts();
  process.stdout.write(
    `[proyecto-create-flow] post-run row counts: ${JSON.stringify(counts)}\n`,
  );
  await prisma.$disconnect();
});

afterEach(() => {
  vi.clearAllMocks();
});

describe("project creation flow (live DB, forced rollback)", () => {
  it("creates a project with an autogenerated code, lists it and persists an edit", async () => {
    const year = new Date().getUTCFullYear();

    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      authAs(usuario.id);

      const createRes = await createProject(
        jsonRequest("http://localhost/api/v1/projects", "POST", {
          nombre: `flow-proyecto-${suffix}`,
          cliente_id: cliente.id,
          responsable_id: usuario.id,
          lineas: [{ id: linea.id, principal: true }],
          municipio_ids: [municipio.id],
          fecha_inicio: "2026-01-05",
          fecha_fin: "2026-03-30",
          valor_total: 1000000,
          beneficiarios_meta: 10,
        }),
      );
      expect(createRes.status).toBe(201);
      const { proyecto } = await createRes.json();
      expect(proyecto.codigo).toMatch(new RegExp(`^PRY-${year}-\\d{3,}$`));
      expect(proyecto.origen).toBe("INDEPENDIENTE");
      expect(proyecto.estado).toBe("BORRADOR");
      expect(proyecto.lineas).toEqual([
        expect.objectContaining({ id: linea.id, principal: true }),
      ]);

      const listRes = await listProjects(new Request("http://localhost/api/v1/projects"));
      expect(listRes.status).toBe(200);
      const { proyectos } = await listRes.json();
      expect(proyectos.some((p: { id: string }) => p.id === proyecto.id)).toBe(true);

      const editRes = await patchProject(
        jsonRequest(`http://localhost/api/v1/projects/${proyecto.id}`, "PATCH", {
          nombre: `flow-editado-${suffix}`,
        }),
        { params: Promise.resolve({ id: proyecto.id }) },
      );
      expect(editRes.status).toBe(200);
      const edited = await editRes.json();
      expect(edited.proyecto.nombre).toBe(`flow-editado-${suffix}`);

      const persisted = await tx.proyecto.findUnique({ where: { id: proyecto.id } });
      expect(persisted?.nombre).toBe(`flow-editado-${suffix}`);

      return { proyectoId: proyecto.id as string };
    });

    expect(result.proyectoId).toBeTruthy();
  });

  it("creating from a GANADA opportunity converts it and audits the conversion + creation in one lote and the team in its own", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      const oportunidad = await tx.oportunidad.create({
        data: {
          cliente_id: cliente.id,
          nombre: `flow-opp-${suffix}`,
          estado: "GANADA",
          valor_estimado_cop: new Prisma.Decimal("500000.00"),
        },
      });
      authAs(usuario.id);

      // E-04 before the conversion: the GANADA opportunity with no project is
      // eligible. This exercises the real `proyecto: { is: null }` relation
      // filter, which the create-path 409 must agree with.
      const eligibleBefore = await listEligible();
      expect(eligibleBefore.status).toBe(200);
      const eligibleBeforeJson = await eligibleBefore.json();
      expect(
        eligibleBeforeJson.oportunidades.some((o: { id: string }) => o.id === oportunidad.id),
      ).toBe(true);

      const res = await createFromOpportunity(
        jsonRequest(
          `http://localhost/api/v1/clients/${cliente.id}/opportunities/${oportunidad.id}/project`,
          "POST",
          {
            responsable_id: usuario.id,
            lineas: [{ id: linea.id, principal: true }],
            municipio_ids: [municipio.id],
            fecha_inicio: "2026-01-05",
            fecha_fin: "2026-03-30",
            beneficiarios_meta: 5,
          },
        ),
        { params: Promise.resolve({ id: cliente.id, opportunityId: oportunidad.id }) },
      );
      expect(res.status).toBe(201);
      const { proyecto } = await res.json();
      expect(proyecto.nombre).toBe(oportunidad.nombre);
      expect(String(proyecto.valor_total)).toBe("500000");

      const converted = await tx.oportunidad.findUnique({ where: { id: oportunidad.id } });
      expect(converted?.fase).toBe("EJECUCION");
      expect(converted?.fecha_adjudicacion).not.toBeNull();

      // Two acts -> two lote_ids: the CONVERTIR + CREAR conversion batch keeps
      // ONE lote (that is what the ficha groups into a single step), and the
      // responsable's membership is its own step with its own lote, so the
      // conversion step renders exactly one "Creación" badge.
      const auditRows = await tx.auditoriaCambio.findMany({
        where: { proyecto_id: proyecto.id },
      });
      expect(auditRows).toHaveLength(3);

      const conversion = auditRows.filter((row) => row.entidad !== "proyecto_miembro");
      expect(conversion.map((row) => `${row.accion}:${row.entidad}`).sort()).toEqual([
        "CONVERTIR:oportunidad",
        "CREAR:proyecto",
      ]);
      const loteConversion = new Set(conversion.map((row) => row.lote_id));
      expect(loteConversion.size).toBe(1);
      expect([...loteConversion][0]).toBeTruthy();

      const equipo = auditRows.filter((row) => row.entidad === "proyecto_miembro");
      expect(equipo).toHaveLength(1);
      expect(equipo[0]).toMatchObject({
        accion: "CREAR",
        entidad: "proyecto_miembro",
        usuario_id: usuario.id,
      });
      expect(equipo[0]!.lote_id).toBeTruthy();
      expect(equipo[0]!.lote_id).not.toBe([...loteConversion][0]);
      const membership = await tx.proyectoMiembro.findFirst({
        where: { proyecto_id: proyecto.id, usuario_id: usuario.id },
      });
      expect(equipo[0]!.entidad_id).toBe(membership!.id);

      // E-04 after the conversion: the opportunity now has a project and must
      // no longer be eligible.
      const eligibleAfter = await listEligible();
      expect(eligibleAfter.status).toBe(200);
      const eligibleAfterJson = await eligibleAfter.json();
      expect(
        eligibleAfterJson.oportunidades.some((o: { id: string }) => o.id === oportunidad.id),
      ).toBe(false);

      return { proyectoId: proyecto.id as string };
    });

    expect(result.proyectoId).toBeTruthy();
  });

  it("does not overwrite fecha_adjudicacion of an already converted opportunity (live DB)", async () => {
    const originalAdjudicacion = new Date("2026-02-03T10:20:30.000Z");

    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      const oportunidad = await tx.oportunidad.create({
        data: {
          cliente_id: cliente.id,
          nombre: `flow-opp-converted-${suffix}`,
          estado: "GANADA",
          fase: "EJECUCION",
          fecha_adjudicacion: originalAdjudicacion,
        },
      });
      authAs(usuario.id);

      const res = await createFromOpportunity(
        jsonRequest(
          `http://localhost/api/v1/clients/${cliente.id}/opportunities/${oportunidad.id}/project`,
          "POST",
          {
            responsable_id: usuario.id,
            lineas: [{ id: linea.id, principal: true }],
            municipio_ids: [municipio.id],
            fecha_inicio: "2026-01-05",
            fecha_fin: "2026-03-30",
          },
        ),
        { params: Promise.resolve({ id: cliente.id, opportunityId: oportunidad.id }) },
      );
      expect(res.status).toBe(201);

      const stored = await tx.oportunidad.findUnique({ where: { id: oportunidad.id } });
      expect(stored?.fase).toBe("EJECUCION");
      // Byte-identical: the write-once branch must not touch the date.
      expect(stored?.fecha_adjudicacion?.toISOString()).toBe(originalAdjudicacion.toISOString());

      return { adjudicacion: stored?.fecha_adjudicacion?.toISOString() };
    });

    expect(result.adjudicacion).toBe("2026-02-03T10:20:30.000Z");
  });

  it("leaves no trace after the rolled-back create flow", async () => {
    const year = new Date().getUTCFullYear();
    const sequenceBefore = await prisma.proyectoSecuencia.findUnique({ where: { anio: year } });

    const createdId = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      authAs(usuario.id);

      const res = await createProject(
        jsonRequest("http://localhost/api/v1/projects", "POST", {
          nombre: `flow-notrace-${suffix}`,
          cliente_id: cliente.id,
          responsable_id: usuario.id,
          lineas: [{ id: linea.id, principal: true }],
          municipio_ids: [municipio.id],
          fecha_inicio: "2026-01-05",
          fecha_fin: "2026-03-30",
        }),
      );
      expect(res.status).toBe(201);
      const { proyecto } = await res.json();
      return proyecto.id as string;
    });

    expect(await prisma.proyecto.count({ where: { id: createdId } })).toBe(0);
    expect(await prisma.auditoriaCambio.count({ where: { entidad_id: createdId } })).toBe(0);
    const sequenceAfter = await prisma.proyectoSecuencia.findUnique({ where: { anio: year } });
    expect(sequenceAfter).toEqual(sequenceBefore);
  });
});

describe("membership on creation (S2.6 T4, live DB, forced rollback)", () => {
  function createBody(
    suffix: string,
    clienteId: string,
    lineaId: string,
    municipioId: string,
    responsableId: string,
    extra: Record<string, unknown> = {},
  ) {
    return {
      nombre: `flow-miembro-${suffix}`,
      cliente_id: clienteId,
      responsable_id: responsableId,
      lineas: [{ id: lineaId, principal: true }],
      municipio_ids: [municipioId],
      fecha_inicio: "2026-01-05",
      fecha_fin: "2026-03-30",
      ...extra,
    };
  }

  it("E-05 adds the responsable as an ACTIVE membership row", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      const oportunidad = await tx.oportunidad.create({
        data: { cliente_id: cliente.id, nombre: `flow-opp-${suffix}`, estado: "GANADA" },
      });
      authAs(usuario.id);

      const res = await createFromOpportunity(
        jsonRequest(
          `http://localhost/api/v1/clients/${cliente.id}/opportunities/${oportunidad.id}/project`,
          "POST",
          {
            responsable_id: usuario.id,
            lineas: [{ id: linea.id, principal: true }],
            municipio_ids: [municipio.id],
            fecha_inicio: "2026-01-05",
            fecha_fin: "2026-03-30",
          },
        ),
        { params: Promise.resolve({ id: cliente.id, opportunityId: oportunidad.id }) },
      );
      expect(res.status).toBe(201);
      const { proyecto } = await res.json();

      // Persisted row, not the returned payload.
      const miembros = await tx.proyectoMiembro.findMany({
        where: { proyecto_id: proyecto.id },
      });
      expect(miembros).toHaveLength(1);
      expect(miembros[0]).toMatchObject({
        usuario_id: usuario.id,
        agregado_por_id: usuario.id,
        removed_at: null,
      });
      return { miembroId: miembros[0]!.id as string };
    });

    expect(result.miembroId).toBeTruthy();
  });

  it("E-03 adds the responsable as an ACTIVE membership row", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      authAs(usuario.id);

      const res = await createProject(
        jsonRequest(
          "http://localhost/api/v1/projects",
          "POST",
          createBody(suffix, cliente.id, linea.id, municipio.id, usuario.id),
        ),
      );
      expect(res.status).toBe(201);
      const { proyecto } = await res.json();

      const miembros = await tx.proyectoMiembro.findMany({
        where: { proyecto_id: proyecto.id },
      });
      expect(miembros).toHaveLength(1);
      expect(miembros[0]).toMatchObject({
        usuario_id: usuario.id,
        agregado_por_id: usuario.id,
        removed_at: null,
      });

      // The team is its own audited act: one CREAR proyecto_miembro row with
      // its own lote, distinct from the project's CREAR row.
      const auditRows = await tx.auditoriaCambio.findMany({
        where: { proyecto_id: proyecto.id },
      });
      const proyectoAudit = auditRows.filter((row) => row.entidad === "proyecto");
      const equipoAudit = auditRows.filter((row) => row.entidad === "proyecto_miembro");
      expect(proyectoAudit).toHaveLength(1);
      expect(equipoAudit).toHaveLength(1);
      expect(equipoAudit[0]).toMatchObject({
        accion: "CREAR",
        usuario_id: usuario.id,
        entidad_id: miembros[0]!.id,
      });
      expect(equipoAudit[0]!.lote_id).not.toBe(proyectoAudit[0]!.lote_id);

      return { miembroId: miembros[0]!.id as string };
    });

    expect(result.miembroId).toBeTruthy();
  });

  it("honours miembro_ids: a supplied active COORDINADOR ends up as an active member", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      const coordinador = await tx.usuario.create({
        data: {
          email: `coord-${suffix}@example.test`,
          nombre: "coord-miembro",
          rol: "COORDINADOR",
        },
      });
      authAs(usuario.id);

      const res = await createProject(
        jsonRequest(
          "http://localhost/api/v1/projects",
          "POST",
          createBody(suffix, cliente.id, linea.id, municipio.id, usuario.id, {
            miembro_ids: [coordinador.id],
          }),
        ),
      );
      expect(res.status).toBe(201);
      const { proyecto } = await res.json();

      const miembros = await tx.proyectoMiembro.findMany({
        where: { proyecto_id: proyecto.id, removed_at: null },
      });
      expect(miembros.map((miembro) => miembro.usuario_id).sort()).toEqual(
        [usuario.id, coordinador.id].sort(),
      );
      return { proyectoId: proyecto.id as string };
    });

    expect(result.proyectoId).toBeTruthy();
  });

  it("collapses a miembro_ids entry naming the responsable into ONE active membership", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      authAs(usuario.id);

      const res = await createProject(
        jsonRequest(
          "http://localhost/api/v1/projects",
          "POST",
          createBody(suffix, cliente.id, linea.id, municipio.id, usuario.id, {
            miembro_ids: [usuario.id],
          }),
        ),
      );
      expect(res.status).toBe(201);
      const { proyecto } = await res.json();

      const miembros = await tx.proyectoMiembro.findMany({
        where: { proyecto_id: proyecto.id, removed_at: null },
      });
      expect(miembros).toHaveLength(1);
      expect(miembros[0]!.usuario_id).toBe(usuario.id);

      // Collapsing means one membership AND one audit row, not two.
      const equipoAudit = await tx.auditoriaCambio.findMany({
        where: { proyecto_id: proyecto.id, entidad: "proyecto_miembro" },
      });
      expect(equipoAudit).toHaveLength(1);
      expect(equipoAudit[0]!.entidad_id).toBe(miembros[0]!.id);
      return { proyectoId: proyecto.id as string };
    });

    expect(result.proyectoId).toBeTruthy();
  });

  it("rejects an invalid miembro_ids entry with 400 and leaves no half-created project", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      const colaborador = await tx.usuario.create({
        data: { email: `colab-${suffix}@example.test`, nombre: "colab-x", rol: "COLABORADOR" },
      });
      const inactivo = await tx.usuario.create({
        data: {
          email: `inactivo-${suffix}@example.test`,
          nombre: "coord-inactivo",
          rol: "COORDINADOR",
          activo: false,
        },
      });
      authAs(usuario.id);

      const proyectosAntes = await tx.proyecto.count();
      const miembrosAntes = await tx.proyectoMiembro.count();

      const casos: [string, string][] = [
        [colaborador.id, "Solo un Coordinador puede ser integrante del equipo del proyecto."],
        [inactivo.id, "El usuario no existe o está inactivo."],
        [randomUUID(), "El usuario no existe."],
      ];
      for (const [miembroId, mensaje] of casos) {
        const res = await createProject(
          jsonRequest(
            "http://localhost/api/v1/projects",
            "POST",
            createBody(suffix, cliente.id, linea.id, municipio.id, usuario.id, {
              miembro_ids: [miembroId],
            }),
          ),
        );
        expect(res.status).toBe(400);
        expect((await res.json()).error).toBe(mensaje);
      }

      expect(await tx.proyecto.count()).toBe(proyectosAntes);
      expect(await tx.proyectoMiembro.count()).toBe(miembrosAntes);
      return { proyectosAntes };
    });

    expect(result.proyectosAntes).toBeGreaterThanOrEqual(0);
  });

  it("E-05 rejects an invalid miembro_ids without converting the opportunity", async () => {
    const result = await runAndRollback(async (tx) => {
      const { suffix, usuario, cliente, linea, municipio } = await seedFixture(tx);
      const colaborador = await tx.usuario.create({
        data: {
          email: `colab-e05-${suffix}@example.test`,
          nombre: "colab-e05",
          rol: "COLABORADOR",
        },
      });
      const oportunidad = await tx.oportunidad.create({
        data: { cliente_id: cliente.id, nombre: `flow-opp-e05-${suffix}`, estado: "GANADA" },
      });
      authAs(usuario.id);

      const res = await createFromOpportunity(
        jsonRequest(
          `http://localhost/api/v1/clients/${cliente.id}/opportunities/${oportunidad.id}/project`,
          "POST",
          {
            responsable_id: usuario.id,
            lineas: [{ id: linea.id, principal: true }],
            municipio_ids: [municipio.id],
            fecha_inicio: "2026-01-05",
            fecha_fin: "2026-03-30",
            miembro_ids: [colaborador.id],
          },
        ),
        { params: Promise.resolve({ id: cliente.id, opportunityId: oportunidad.id }) },
      );
      expect(res.status).toBe(400);
      expect((await res.json()).error).toBe(
        "Solo un Coordinador puede ser integrante del equipo del proyecto.",
      );

      const stored = await tx.oportunidad.findUnique({ where: { id: oportunidad.id } });
      expect(stored?.fase).not.toBe("EJECUCION");
      expect(stored?.fecha_adjudicacion).toBeNull();
      expect(await tx.proyecto.count({ where: { oportunidad_id: oportunidad.id } })).toBe(0);
      return { oportunidadId: oportunidad.id };
    });

    expect(result.oportunidadId).toBeTruthy();
  });
});
